use crate::token::{format_token, Token};

pub fn login(raw: &str) -> Result<String, String> {
    let token = Token::verify(raw, 0)?;
    Ok(format!("session:{}", format_token(&token)))
}

use crate::token::Token;

pub fn bind(raw: &str) -> Result<Token, String> {
    Token::verify(raw, 0)
}

pub struct Token {
    pub raw: String,
    pub expires_at: u64,
}

pub fn format_token(token: &Token) -> String {
    format!("token(expires_at={})", token.expires_at)
}

impl Token {
    pub fn verify(raw: &str, now: u64) -> Result<Self, String> {
        if raw.is_empty() {
            return Err("empty".into());
        }

        // A token may carry its expiry as a final `:unix_timestamp` field.
        let expires_at = raw
            .rsplit_once(':')
            .and_then(|(_, expires_at)| expires_at.parse::<u64>().ok())
            .unwrap_or(u64::MAX);

        if now >= expires_at {
            return Err("expired".into());
        }

        Ok(Self {
            raw: raw.to_string(),
            expires_at,
        })
    }
}
